// HasApplication applies the HasEdge predicate on the "application" edge.
func HasApplication() predicate.ShopApplicationMessage {
	return predicate.ShopApplicationMessage(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, ApplicationTable, ApplicationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasApplicationWith applies the HasEdge predicate on the "application" edge with a given conditions (other predicates).
func HasApplicationWith(preds ...predicate.ShopApplication) predicate.ShopApplicationMessage {
	return predicate.ShopApplicationMessage(func(s *sql.Selector) {
		step := newApplicationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ShopApplicationMessage) predicate.ShopApplicationMessage {
	return predicate.ShopApplicationMessage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ShopApplicationMessage) predicate.ShopApplicationMessage {
	return predicate.ShopApplicationMessage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ShopApplicationMessage) predicate.ShopApplicationMessage {
	return predicate.ShopApplicationMessage(sql.NotPredicates(p))
}
